---@class MonsterConfig
local MonsterConfig = T(Global, "MonsterConfig")
---@type MonsterRewardConfig
local MonsterRewardConfig = T(Global, "MonsterRewardConfig")
---@type MonsterConfigData[]
local ConfigList = {}

---@private
function MonsterConfig:init()
    local config = FileUtil.getGameConfigFromCsv("monster/Monster.csv")
    for _, item in pairs(config or {}) do
        ---@class MonsterConfigData
        local data = {}
        data.id = tonumber(item.id)
        data.type = tonumber(item.type)
        data.spawnTip = item.spawnTip or "#"
        data.hp = tonumber(item.hp)
        data.attack = tonumber(item.attack)
        data.defence = tonumber(item.defence)
        data.name = item.name == "#" and "" or item.name
        data.icon = item.icon
        data.actorName = item.actorName
        if isServer then
            data.dieRewards = MonsterRewardConfig:getCfgByGroupIds(item.rewardGroupId)
        end
        data.dieRewardCount = tonumber(item.dieRewardCount) or 0
        data.dieChestActor = item.dieChestActor or "#"
        data.dieEffect = item.dieEffect or "#"
        data.buffIds = StringUtil.split(item.buffIds or "", "#", nil, true)
        data.effectScale = tonumber(item.effectScale) or 1
        data.showBloodBarDis = tonumber(item.showBloodBarDis) or 1000
        data.showDamageRank = item.showDamageRank == "1"
        data.isBoss = data.hp >= 1000
        data.exp = tonumber(item.exp) or 0
        data.hitBox = StringUtil.split(item.hitBox, ",", nil, true)
        ConfigList[data.id] = data

        if isServer then
            local monster = MonsterSetting.new()
            monster.monsterId = data.id
            monster.monsterBtTree = "MonsterG1049"
            monster.monsterType = 5
            monster.isAutoAttack = true
            monster.attackDistance = tonumber(item.attackDistance)
            monster.attackCd = tonumber(item.attackCD)
            monster.attackCount = 1
            monster.moveSpeed = tonumber(item.moveSpeed)
            monster.attackType = 0
            monster.patrolDistance = tonumber(item.patrolDistance)
            monster.skillId = 0
            monster.skillCd = 0
            monster.viewRange = tonumber(item.viewRange)
            monster.viewDegree = tonumber(item.viewDegree)
            monster.moveSpeedAddition = tonumber(item.moveSpeedAddition)
            monster.canFly = item.canFly == "1"
            monster.flyHigh = tonumber(item.flyHigh)
            monster.canEscape = item.canEscape == "1"
            monster.patrolType = tonumber(item.patrolType)
            monster.patrolDistanceOnce = tonumber(item.patrolDistanceOnce)
            monster.patrolCD = tonumber(item.patrolCD)
            monster.alertTime = tonumber(item.alertTime)
            monster.pursueDistance = tonumber(item.pursueDistance)
            monster.canTogether = tonumber(item.canTogether)
            monster.togetherRange = tonumber(item.togetherRange)
            HostApi.addMonsterSetting(monster)
        end
    end
end

---@return MonsterConfigData
function MonsterConfig:getCfgById(id)
    return ConfigList[id]
end

---@return MonsterConfigData
function MonsterConfig:getCfgByType(type)
    for _, cfg in pairs(ConfigList) do
        if cfg.type == type then
            return cfg
        end
    end
    return nil
end

MonsterConfig:init()

return MonsterConfig